public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Find the minimum string length to bound the search
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s != null) {
            minLen = Math.min(minLen, s.length());
        } else {
            return 0; // null string makes it impossible to find a substring
        }
    }

    // Helper to reverse a string
    java.util.function.Function<String, String> reverse = str -> new StringBuilder(str).reverse().toString();

    // Check lengths from longest possible to 1
    for (int len = minLen; len >= 1; len--) {
        // Build a set of candidate substrings (and their reverses)
        java.util.HashSet<String> candidates = new java.util.HashSet<>();
        for (String s : strings) {
            for (int i = 0; i + len <= s.length(); i++) {
                String sub = s.substring(i, i + len);
                candidates.add(sub);
                candidates.add(reverse.apply(sub));
            }
        }

        // Test each candidate
        for (String cand : candidates) {
            boolean ok = true;
            String revCand = reverse.apply(cand);
            for (String t : strings) {
                if (!(t.contains(cand) || t.contains(revCand))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

