    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    int maxLen = first.length();
    for (int len = maxLen; len >= 1; len--) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        boolean found = false;
        for (int i = 0; i <= maxLen - len; i++) {
            String candidate = first.substring(i, i + len);
            if (!seen.add(candidate)) {
                continue; // skip duplicates
            }
            String revCandidate = new StringBuilder(candidate).reverse().toString();
            boolean allContain = true;
            for (int s = 1; s < strings.size(); s++) {
                String target = strings.get(s);
                if (!(target.contains(candidate) || target.contains(revCandidate))) {
                    allContain = false;
                    break;
                }
            }
            if (allContain) {
                found = true;
                break;
            }
        }
        if (found) {
            return len;
        }
    }
    return 0;
}

