public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate to a unique key
    java.util.function.Function<int[], String> key = coord -> coord[0] + "," + coord[1];

    // Quick check: if start equals end
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Build adjacency map from paths
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p.length != 4) continue; // invalid path, skip
        int[] a = {p[0], p[1]};
        int[] b = {p[2], p[3]};
        String ka = key.apply(a);
        String kb = key.apply(b);
        adj.computeIfAbsent(ka, k -> new java.util.ArrayList<>()).add(kb);
        adj.computeIfAbsent(kb, k -> new java.util.ArrayList<>()).add(ka);
    }

    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.ArrayDeque<String> queue = new java.util.ArrayDeque<>();
    String startKey = key.apply(start);
    String endKey = key.apply(end);
    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.getOrDefault(cur, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (visited.contains(nb)) continue;
            if (nb.equals(endKey)) {
                return "can be travelled";
            }
            visited.add(nb);
            queue.offer(nb);
        }
    }
    return "cannot be travelled";
}

