public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length != end.length) {
        throw new IllegalArgumentException("Start and end coordinates must be non-null and of the same dimension.");
    }
    int dimension = start.length;
    if (n <= 0) {
        throw new IllegalArgumentException("Grid size must be positive.");
    }
    // Compute total number of nodes in the n-dimensional grid
    int totalNodes = 1;
    for (int i = 0; i < dimension; i++) {
        totalNodes *= n;
    }

    // Helper to map a coordinate array to a unique node id
    int coordToId(int[] coords) {
        int id = 0;
        int multiplier = 1;
        for (int i = 0; i < coords.length; i++) {
            int value = coords[i];
            if (value < 0 || value >= n) {
                throw new IllegalArgumentException("Coordinate out of bounds: " + value);
            }
            id += value * multiplier;
            multiplier *= n;
        }
        return id;
    }

    int startId = coordToId(start);
    int endId = coordToId(end);

    // Build adjacency list
    @SuppressWarnings("unchecked")
    List<Integer>[] adj = new ArrayList[totalNodes];
    for (int i = 0; i < totalNodes; i++) {
        adj[i] = new ArrayList<>();
    }
    for (int[] edge : paths) {
        if (edge == null || edge.length != 2) {
            continue; // ignore malformed edges
        }
        int a = edge[0];
        int b = edge[1];
        if (a < 0 || a >= totalNodes || b < 0 || b >= totalNodes) {
            continue; // skip invalid indices
        }
        adj[a].add(b);
        adj[b].add(a); // assuming undirected paths
    }

    // Breadth‑first search to check connectivity
    boolean[] visited = new boolean[totalNodes];
    Deque<Integer> queue = new ArrayDeque<>();
    queue.add(startId);
    visited[startId] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == endId) {
            return "can be travelled";
        }
        for (int neighbor : adj[current]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

