public static String appx(String word1, String word2) {
    Set<Character> set1 = new HashSet<>();
    for (char c : word1.toCharArray()) {
        set1.add(c);
    }
    Set<Character> set2 = new HashSet<>();
    for (char c : word2.toCharArray()) {
        set2.add(c);
    }
    int commonCount = 0;
    for (char c : set1) {
        if (set2.contains(c)) {
            commonCount++;
        }
    }
    int numerator = 2 * commonCount;
    int denominator = word1.length() + word2.length();
    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    if (numerator == denominator) {
        return "appx(" + word1 + ", " + word2 + ") = 1";
    }
    int gcd = gcd(numerator, denominator);
    int redNumerator = numerator / gcd;
    int redDenominator = denominator / gcd;
    if (redNumerator == 1 && redDenominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = 1";
    }
    return "appx(" + word1 + ", " + word2 + ") = " + redNumerator + "/" + redDenominator;
}

