public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k > n || k <= 0) return false;
    int required = 1 << k;
    boolean[] seen = new boolean[required];
    int count = 0;
    int val = 0;
    // Build first window
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    if (!seen[val]) {
        seen[val] = true;
        count++;
    }
    int mask = required - 1;
    for (int i = k; i < n; i++) {
        val = ((val << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[val]) {
            seen[val] = true;
            count++;
            if (count == required) return true;
        }
    }
    return count == required;
}

