public int maxUniqueSplit(String s) {
    int n = s.length();
    if (n == 0) {
        return 0;
    }
    int max = 0;
    int totalMasks = 1 << (n - 1);
    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        int start = 0;
        boolean valid = true;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) {
                String sub = s.substring(start, i + 1);
                if (!seen.add(sub)) {
                    valid = false;
                    break;
                }
                start = i + 1;
            }
        }
        if (!valid) {
            continue;
        }
        String last = s.substring(start, n);
        if (!seen.add(last)) {
            continue;
        }
        int size = seen.size();
        if (size > max) {
            max = size;
        }
    }
    return max;
}

