public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new java.util.ArrayList<>();
    if (low <= 0 && high >= 0) {
        result.add(0);
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int d = 1; d <= 9; d++) {
        queue.offer((long)d);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int)num);
        }
        long lastDigit = num % 10;
        if (num > high / 10) {
            continue; // children would definitely exceed high
        }
        if (lastDigit > 0) {
            long child = num * 10 + (lastDigit - 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
        if (lastDigit < 9) {
            long child = num * 10 + (lastDigit + 1);
            if (child <= high) {
                queue.offer(child);
            }
        }
    }
    return result;
}

