public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][][] dp = new int[m][n][4];
    int ans = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = 1 + (j > 0 ? dp[i][j - 1][0] : 0);                 // horizontal
                dp[i][j][1] = 1 + (i > 0 ? dp[i - 1][j][1] : 0);                 // vertical
                dp[i][j][2] = 1 + (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0);     // diagonal
                dp[i][j][3] = 1 + (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0); // anti-diagonal
                int localMax = Math.max(Math.max(dp[i][j][0], dp[i][j][1]),
                                         Math.max(dp[i][j][2], dp[i][j][3]));
                if (localMax > ans) {
                    ans = localMax;
                }
            }
        }
    }
    return ans;
}

