    boolean isNegative = n < 0;
    int absValue = Math.abs(n);
    String numStr = Integer.toString(absValue);
    StringBuilder sb = new StringBuilder();
    for (int i = numStr.length() - 1, count = 0; i >= 0; i--, count++) {
        sb.insert(0, numStr.charAt(i));
        if (count % 3 == 2 && i != 0) {
            sb.insert(0, '.');
        }
    }
    if (isNegative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

