public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    long abs = Math.abs((long) n);
    if (abs == 0) return "0";
    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (abs > 0) {
        long digit = abs % 10;
        sb.append(digit);
        abs /= 10;
        count++;
        if (count == 3 && abs > 0) {
            sb.append('.');
            count = 0;
        }
    }
    if (negative) sb.append('-');
    return sb.reverse().toString();
}

