public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Find maximum value to limit square precomputation
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    // Build adjacency matrix
    boolean[][] adj = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            int sum = A[i] + A[j];
            boolean ok = sum <= maxSum && isSquare[sum];
            adj[i][j] = adj[j][i] = ok;
        }
    }
    int totalMask = 1 << n;
    int[][] dp = new int[totalMask][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    for (int mask = 0; mask < totalMask; mask++) {
        for (int last = 0; last < n; last++) {
            int curCount = dp[mask][last];
            if (curCount == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (!adj[last][next]) continue;
                int newMask = mask | (1 << next);
                dp[newMask][next] += curCount;
            }
        }
    }
    int fullMask = totalMask - 1;
    int result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[fullMask][i];
    }
    return result;
}

