public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    for (int d = 0; d < m + n - 1; d++) {
        int r = Math.min(d, m - 1);
        int c = d - r;
        if (d % 2 == 0) {
            while (r >= 0 && c < n) {
                result[index++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            while (c >= 0 && r < m) {
                result[index++] = mat[r][c];
                r++;
                c--;
            }
        }
    }
    return result;
}

