public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    if (isPerfectSquare(n)) return 1;
    for (int i = 1; i * i <= n; i++) {
        int remainder = n - i * i;
        if (isPerfectSquare(remainder)) return 2;
    }
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) return 4;
    return 3;
}

