    int start = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == ' ') {
            for (int j = i - 1; j >= start; j--) {
                sb.append(s.charAt(j));
            }
            sb.append(' ');
            start = i + 1;
        }
    }
    for (int j = s.length() - 1; j >= start; j--) {
        sb.append(s.charAt(j));
    }
    return sb.toString();
}

